/* Main footer wrapper */
#mp-footer {
  margin-top: -3rem;
    padding-left: 20px;
}

#mp-footer .mp-footer-inner {
  border-top: 1px solid #444;
  padding-top: 0.5rem;
}


/* Flex container */
#mp-footer .mp-footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
}

/* Left column */
#mp-footer .mp-footer-left {
  text-align: left;
  font-size: 1rem;
  padding-left: 0px;
}

/* Right column */
#mp-footer .mp-footer-right {
  text-align: right;
  font-size: 1rem;
}
